class MyApp extends StatefulWidget {
  @override
  _MyAppState createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  int counter = 0;
  String lastAction = 'Нажмите любую кнопку';

  void handlePress(String action) {
    setState(() {
      counter++;
      lastAction = action;
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text('Кнопки Flutter')),
        body: Center(
          child: Padding(
            padding: EdgeInsets.all(16.0),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                // Счетчик нажатий
                Text(
                  'Нажатий: $counter',
                  style: TextStyle(
                    fontSize: 24,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                SizedBox(height: 10),
                Text(
                  lastAction,
                  style: TextStyle(fontSize: 16, color: Colors.grey),
                ),
                SizedBox(height: 30),

                // ElevatedButton - основная кнопка
                ElevatedButton(
                  onPressed: () => handlePress('ElevatedButton нажата'),
                  child: Text('ElevatedButton'),
                ),
                SizedBox(height: 10),

                // ElevatedButton с иконкой
                ElevatedButton.icon(
                  onPressed: () => handlePress('Кнопка с иконкой'),
                  icon: Icon(Icons.send),
                  label: Text('Отправить'),
                ),
                SizedBox(height: 20),

                // TextButton - текстовая кнопка
                TextButton(
                  onPressed: () => handlePress('TextButton нажата'),
                  child: Text('TextButton'),
                ),
                SizedBox(height: 20),

                // OutlinedButton - кнопка с границей
                OutlinedButton(
                  onPressed: () => handlePress('OutlinedButton нажата'),
                  child: Text('OutlinedButton'),
                ),
                SizedBox(height: 20),

                // Ряд IconButton
                Text('IconButton:'),
                SizedBox(height: 10),
                Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    IconButton(
                      icon: Icon(Icons.favorite_border),
                      color: Colors.red,
                      iconSize: 30,
                      onPressed: () => handlePress('Сердце'),
                    ),
                    IconButton(
                      icon: Icon(Icons.share),
                      color: Colors.blue,
                      iconSize: 30,
                      onPressed: () => handlePress('Поделиться'),
                    ),
                    IconButton(
                      icon: Icon(Icons.bookmark_border),
                      color: Colors.green,
                      iconSize: 30,
                      onPressed: () => handlePress('Закладка'),
                    ),
                  ],
                ),
                SizedBox(height: 20),

                // Кнопка с настраиваемым стилем
                ElevatedButton(
                  onPressed: () => handlePress('Красивая кнопка'),
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.purple,
                    foregroundColor: Colors.white,
                    padding: EdgeInsets.symmetric(
                      horizontal: 40,
                      vertical: 15,
                    ),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(30),
                    ),
                  ),
                  child: Text(
                    'Кастомная кнопка',
                    style: TextStyle(fontSize: 16),
                  ),
                ),
                SizedBox(height: 20),

                // Неактивная кнопка (onPressed = null)
                ElevatedButton(
                  onPressed: null, // неактивна
                  child: Text('Неактивная кнопка'),
                ),
              ],
            ),
          ),
        ),
        // FloatingActionButton
        floatingActionButton: FloatingActionButton(
          onPressed: () => handlePress('FAB нажата'),
          child: Icon(Icons.add),
          tooltip: 'Добавить',
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';

void main() => runApp(MyApp());

class MyApp extends StatelessWidget {
  Widget buildBox(String text, Color color) {
    return Container(
      width: 80,
      height: 80,
      decoration: BoxDecoration(
        color: color,
        borderRadius: BorderRadius.circular(10),
        boxShadow: [
          BoxShadow(
            color: Colors.black26,
            blurRadius: 5,
            offset: Offset(2, 2),
          ),
        ],
      ),
      child: Center(
        child: Text(
          text,
          style: TextStyle(
            color: Colors.white,
            fontWeight: FontWeight.bold,
          ),
          textAlign: TextAlign.center,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      home: Scaffold(
        appBar: AppBar(title: Text('Center и Align')),
        body: SingleChildScrollView(
          child: Column(
            children: [
              // Center пример
              Container(
                height: 200,
                color: Colors.grey[200],
                child: Center(
                  child: buildBox('Center', Colors.blue),
                ),
              ),

              Padding(
                padding: EdgeInsets.all(16),
                child: Text(
                  'Align - разные позиции:',
                  style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),

              // Align примеры - 9 позиций
              Container(
                height: 400,
                margin: EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: Colors.grey[200],
                  border: Border.all(color: Colors.blue, width: 2),
                  borderRadius: BorderRadius.circular(10),
                ),
                child: Stack(
                  children: [
                    // Верхний левый
                    Align(
                      alignment: Alignment.topLeft,
                      child: buildBox('TL', Colors.red),
                    ),
                    // Верх центр
                    Align(
                      alignment: Alignment.topCenter,
                      child: buildBox('TC', Colors.orange),
                    ),
                    // Верхний правый
                    Align(
                      alignment: Alignment.topRight,
                      child: buildBox('TR', Colors.yellow[700]!),
                    ),
                    // Слева центр
                    Align(
                      alignment: Alignment.centerLeft,
                      child: buildBox('CL', Colors.green),
                    ),
                    // Центр
                    Align(
                      alignment: Alignment.center,
                      child: buildBox('C', Colors.blue),
                    ),
                    // Справа центр
                    Align(
                      alignment: Alignment.centerRight,
                      child: buildBox('CR', Colors.indigo),
                    ),
                    // Нижний левый
                    Align(
                      alignment: Alignment.bottomLeft,
                      child: buildBox('BL', Colors.purple),
                    ),
                    // Низ центр
                    Align(
                      alignment: Alignment.bottomCenter,
                      child: buildBox('BC', Colors.pink),
                    ),
                    // Нижний правый
                    Align(
                      alignment: Alignment.bottomRight,
                      child: buildBox('BR', Colors.brown),
                    ),
                  ],
                ),
              ),

              Padding(
                padding: EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      'Кастомное выравнивание:',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                    SizedBox(height: 10),
                    Container(
                      height: 200,
                      decoration: BoxDecoration(
                        color: Colors.grey[200],
                        borderRadius: BorderRadius.circular(10),
                      ),
                      child: Stack(
                        children: [
                          // Кастомная позиция 1
                          Align(
                            alignment: Alignment(-0.5, -0.5),
                            child: buildBox('A', Colors.teal),
                          ),
                          // Кастомная позиция 2
                          Align(
                            alignment: Alignment(0.7, 0.3),
                            child: buildBox('B', Colors.cyan),
                          ),
                        ],
                      ),
                    ),
                    SizedBox(height: 10),
                    Text(
                      'TL=TopLeft, TC=TopCenter, TR=TopRight\n'
                      'CL=CenterLeft, C=Center, CR=CenterRight\n'
                      'BL=BottomLeft, BC=BottomCenter, BR=BottomRight',
                      style: TextStyle(fontSize: 12, color: Colors.grey[600]),
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

