class MyPageViewExample extends StatefulWidget {
  @override
  _MyPageViewExampleState createState() => _MyPageViewExampleState();
}

class _MyPageViewExampleState extends State<MyPageViewExample> {
  final PageController _pageController = PageController();
  int _currentPage = 0;

  final List<OnboardingPage> pages = [
    OnboardingPage(
      title: 'Добро пожаловать!',
      description: 'Это пример онбординга с помощью PageView',
      icon: Icons.waving_hand,
      color: Colors.blue,
    ),
    OnboardingPage(
      title: 'Простота',
      description: 'Свайпайте влево и вправо чтобы листать страницы',
      icon: Icons.touch_app,
      color: Colors.green,
    ),
    OnboardingPage(
      title: 'Готово!',
      description: 'Теперь вы знаете как работает PageView',
      icon: Icons.check_circle,
      color: Colors.purple,
    ),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Stack(
        children: [
          // PageView с страницами
          PageView.builder(
            controller: _pageController,
            onPageChanged: (index) {
              setState(() {
                _currentPage = index;
              });
            },
            itemCount: pages.length,
            itemBuilder: (context, index) {
              return Container(
                color: pages[index].color,
                child: SafeArea(
                  child: Padding(
                    padding: EdgeInsets.all(40),
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Icon(
                          pages[index].icon,
                          size: 150,
                          color: Colors.white,
                        ),
                        SizedBox(height: 40),
                        Text(
                          pages[index].title,
                          style: TextStyle(
                            fontSize: 32,
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                          textAlign: TextAlign.center,
                        ),
                        SizedBox(height: 20),
                        Text(
                          pages[index].description,
                          style: TextStyle(
                            fontSize: 18,
                            color: Colors.white70,
                          ),
                          textAlign: TextAlign.center,
                        ),
                      ],
                    ),
                  ),
                ),
              );
            },
          ),

          // Индикаторы страниц
          Positioned(
            bottom: 40,
            left: 0,
            right: 0,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: List.generate(
                pages.length,
                (index) => AnimatedContainer(
                  duration: Duration(milliseconds: 300),
                  margin: EdgeInsets.symmetric(horizontal: 4),
                  width: _currentPage == index ? 24 : 8,
                  height: 8,
                  decoration: BoxDecoration(
                    color: _currentPage == index
                        ? Colors.white
                        : Colors.white54,
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
              ),
            ),
          ),

          // Кнопка "Далее" или "Начать"
          Positioned(
            bottom: 100,
            right: 20,
            child: _currentPage == pages.length - 1
                ? ElevatedButton(
                    onPressed: () {
                      // Закрыть онбординг
                      Navigator.pop(context);
                    },
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.white,
                      foregroundColor: pages[_currentPage].color,
                      padding: EdgeInsets.symmetric(
                        horizontal: 32,
                        vertical: 16,
                      ),
                    ),
                    child: Text(
                      'Начать',
                      style: TextStyle(fontSize: 16),
                    ),
                  )
                : FloatingActionButton(
                    onPressed: () {
                      _pageController.nextPage(
                        duration: Duration(milliseconds: 400),
                        curve: Curves.easeInOut,
                      );
                    },
                    backgroundColor: Colors.white,
                    child: Icon(
                      Icons.arrow_forward,
                      color: pages[_currentPage].color,
                    ),
                  ),
          ),

          // Кнопка "Пропустить"
          if (_currentPage < pages.length - 1)
            Positioned(
              top: 50,
              right: 20,
              child: TextButton(
                onPressed: () {
                  _pageController.animateToPage(
                    pages.length - 1,
                    duration: Duration(milliseconds: 400),
                    curve: Curves.easeInOut,
                  );
                },
                child: Text(
                  'Пропустить',
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 16,
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  @override
  void dispose() {
    _pageController.dispose();
    super.dispose();
  }
}

class OnboardingPage {
  final String title;
  final String description;
  final IconData icon;
  final Color color;

  OnboardingPage({
    required this.title,
    required this.description,
    required this.icon,
    required this.color,
  });
}
